'use strict';
const paths={leaf:'<path d="M5 17C2 9 10 3 21 3c0 11-6 18-14 16"/><path d="M3 22 17 8"/>',home:'<path d="m3 10 9-7 9 7v11H3Z"/><path d="M9 21v-8h6v8"/>',gesture:'<path d="M8 15V8a2 2 0 0 1 4 0v5-9a2 2 0 0 1 4 0v9-5a2 2 0 0 1 4 0v9c0 4-3 5-7 5-3 0-5-2-6-4L3 13c-1-2 1-4 3-2l2 2"/>',settings:'<path d="M5 5h14M5 12h14M5 19h14"/><circle cx="9" cy="5" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="8" cy="19" r="2" fill="currentColor"/>',region:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><rect x="8" y="8" width="8" height="8" rx="1"/>',long:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M9 7h6m-3 3v8m-3-3 3 3 3-3"/>',screen:'<rect x="3" y="5" width="18" height="16" rx="3"/><circle cx="12" cy="13" r="4"/><path d="M8 2h8"/>',record:'<rect x="2" y="5" width="14" height="14" rx="3"/><path d="m16 10 6-3v10l-6-3"/>',gif:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M8 9H6v6h3v-3H7m5-3v6m3 0V9h4m-4 3h3"/>',recent:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',star:'<path d="m12 2 3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1Z"/>',notes:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8m-8 4h8m-8 4h5"/>',browser:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',pause:'<path d="M9 6v12m6-12v12"/>',play:'<path d="m8 4 12 8-12 8Z"/>',back:'<path d="m15 5-7 7 7 7"/>',next:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 5 5 10-10"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',manage:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><path d="m14 20 6-6m-5 1 4 4"/>',save:'<path d="M4 3h14l3 3v15H3V3Z"/><path d="M7 3v6h10V3M7 21v-7h10v7"/>',share:'<circle cx="5" cy="12" r="2.5"/><circle cx="19" cy="5" r="2.5"/><circle cx="19" cy="19" r="2.5"/><path d="m7 11 10-5M7 13l10 5"/>',edit:'<path d="m4 16-1 5 5-1L21 7l-5-5Z"/><path d="m13 5 5 5"/>',copy:'<rect x="7" y="7" width="14" height="14" rx="2"/><path d="M16 4V3H3v13h1"/>',translate:'<path d="M2 5h12M8 2v3m-4 3c1 4 4 7 9 9M12 5c-1 6-4 10-9 13m12 3 4-11 4 11m-7-3h6"/>',crop:'<path d="M7 2v15h15M2 7h15v15"/>',rotate:'<path d="M4 8a9 9 0 1 1 0 9M3 2v7h7"/>',rect:'<rect x="3" y="5" width="18" height="15" rx="1"/>',arrow:'<path d="m4 20 16-16M7 4h13v13"/>',text:'<path d="M3 4h18M12 4v17M8 21h8"/>',pen:'<path d="M2 17c8-15 3 11 9-1s4 9 11-3"/>',mosaic:'<path d="M4 4h6v6H4Zm10 10h6v6h-6ZM14 4h6v6h-6ZM4 14h6v6H4Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8c1-4 8-2 6 2l-3 3m0 4h.01"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',pin:'<path d="M7 3h11l-2 6 4 4H6l4-4Zm6 10-6 9"/>',notification:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4Zm5 3h4"/>'};
function icon(id,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[id]||paths.leaf}</svg>`}
const tools=[['region','区域截图'],['long','长截图'],['screen','整屏截图'],['record','录屏'],['gif','录制 GIF'],['recent','最近应用'],['star','常用应用'],['notes','便签'],['browser','浏览器']];
const concepts=[{id:'quark',name:'清爽工具箱',en:'CLEAR & QUICK',ref:'夸克',url:'https://uinotes.com/app/484993995075349049',note:'信息紧凑、操作直达。最适合功能多、经常使用的悬浮工具。',rate:4},{id:'nine',name:'深色控制台',en:'CONTROL CENTER',ref:'九号出行 · 控制结构',url:'https://uinotes.com/app/404881484907886222',note:'围绕悬浮球状态组织功能。深色与荧光绿更有设备控制感。',rate:3},{id:'offscreen',name:'暖色小卡片',en:'SOFT EVERYDAY',ref:'OffScreen',url:'https://uinotes.com/app/407746994022662004',note:'柔和奶油色、轻松的卡片节奏。适合有温度的日常小工具。',rate:3},{id:'stress',name:'薄荷小伙伴',en:'LITTLE COMPANION',ref:'StressWatch',url:'https://uinotes.com/app/385556095364697570',note:'状态拟人化，工具采用大小卡片。保留“小叶”的轻盈和亲和力。',rate:4}];
concepts.push(
{id:'garden',name:'绿意拼贴',en:'A LITTLE GREEN, EVERYWHERE',ref:'用户提供的植物应用参考',url:null,note:'橄榄绿、嫩叶绿与几何植物拼贴。清新的植物感，让工具也像一座随手花园。',rate:4},
{id:'forest',name:'森系品牌',en:'KONGYE / YOUR EVERYDAY COMPANION',ref:'用户提供的 greenfiber 品牌参考',url:null,note:'米白底与森林绿，采用粗字体、胶囊组件和叶形标识。更克制，也更有品牌辨识度。',rate:4});
const botanicalOnly=new URLSearchParams(location.search).get('view')==='botanical';
if(botanicalOnly)document.body.classList.add('botanical-only');
const state=concepts.map(()=>({page:'home',running:true,permissions:[true,false,true],size:48,opacity:90,gap:0,color:null,selected:tools.filter(x=>x[0]!=='star').map(x=>x[0]),gestures:['快捷菜单','返回','边缘快捷栏','打开空叶软件页面','通知栏'],notes:'',theme:'跟随系统',switches:[true,true,true,true],sound:'无声',recording:false,pinned:false}));
const board=document.getElementById('board');
board.innerHTML=concepts.map((c,i)=>`<article class="concept"><div class="concept-head"><b>${c.name}</b><span class="number">0${i+1}</span></div><section class="phone ${c.id}" data-phone="${i}" aria-label="方案 ${i+1} ${c.name}"><div class="camera"></div><div class="status"><span>9:41</span><svg viewBox="0 0 50 12" fill="currentColor" aria-hidden="true"><path d="M1 9h2v2H1Zm4-3h2v5H5Zm4-3h2v8H9Zm4-3h2v11h-2Z"/><path d="M22 4q6-6 12 0l-2 2q-4-4-8 0Zm4 4q2-2 4 0l-2 3Z"/><rect x="38" y="2" width="10" height="7" rx="2"/><path d="M49 4h1v3h-1"/></svg></div><header class="apphead"><div><div class="heading-row">${icon('leaf','leaf-mini')}<span class="wordmark">空叶悬浮球</span></div><div class="brand-sub">${c.en}</div></div><button class="icon-button" data-action="about" aria-label="关于空叶">${icon('help')}</button></header><main class="viewport"></main><nav class="nav" aria-label="应用导航">${[['home','home','首页'],['gesture','gesture','手势'],['settings','settings','外观']].map(([p,ic,n])=>`<button data-page="${p}">${icon(ic)}${n}</button>`).join('')}</nav><div class="bar"></div><button class="floating-ball" data-action="quick" aria-label="打开悬浮球快捷面板">${icon('leaf')}</button></section><p class="style-note">${c.note}</p><div class="row comparison-tip">${c.url?`<a class="source" href="${c.url}" target="_blank" rel="noreferrer">参考：${c.ref} ↗</a>`:`<span class="source">参考：${c.ref}</span>`}${i===0?'<span class="recommend">工具型首选</span>':i===3?'<span class="recommend">个性型首选</span>':''}</div></article>`).join('');
function section(title,action,label=''){return `<div class="section-head"><h3>${title}</h3>${action?`<button class="text-button" data-action="${action}">${label||'管理'}</button>`:''}</div>`}
function permissionList(i){return `<div class="card permission-list">${[['悬浮窗','让小叶显示在其他应用上方'],['无障碍','导航、截图与长截图需要'],['通知','显示运行状态与停止入口']].map(([n,d],j)=>`<div class="permission-row"><div class="permission-label">${n}<small>${d}</small></div><button class="permission-chip ${state[i].permissions[j]?'':'off'}" data-action="permission" data-index="${j}">${state[i].permissions[j]?'✓ 已开启':'去开启'}</button></div>`).join('')}</div>`}
function toolGrid(i){return `<div class="tools-wrap"><div class="tools">${state[i].selected.map(id=>{let t=tools.find(t=>t[0]===id);return `<button class="tool" data-action="tool" data-tool="${id}"><span class="tool-icon">${icon(id)}</span><span>${t[1]}</span></button>`}).join('')}</div></div>`}
function runCard(i){let s=state[i],c=concepts[i];if(c.id==='nine')return `<div class="console"><div class="console-header"><span>FLOAT / DEVICE</span><span>${s.running?'● ONLINE':'○ PAUSED'}</span></div><div class="orbit">${icon('leaf')}</div><h3>${s.running?'空叶已就绪':'空叶已暂停'}</h3><small>${s.running?'你的屏幕，现在由你掌控':'轻触按钮，重新连接小叶'}</small><div class="console-grid"><div><b>${s.size} dp</b><span>球体尺寸</span></div><div><b>${s.opacity}%</b><span>不透明度</span></div><div><b>${s.selected.length}</b><span>常用工具</span></div></div><button class="primary" data-action="running">${icon(s.running?'pause':'play').replace('<svg ','<svg style="height:11px;width:11px;vertical-align:-2px;margin-right:4px" ')}${s.running?'暂停悬浮球':'开启悬浮球'}</button></div>`;return `${c.id==='offscreen'?'<div class="day-chip">☀ 今天，也轻松一点</div>':''}<div class="card running">${c.id==='stress'?'<div class="mascot"></div>':''}<div><div class="run-status"><span class="dot"></span>${s.running?(c.id==='stress'?'小叶在这里':'悬浮球正在运行'):'悬浮球已暂停'}</div><div class="run-note">${s.running?'随时为你打开常用工具':'轻触右侧按钮，继续使用'}</div></div><button class="primary state-button" data-action="running" aria-label="${s.running?'暂停':'开启'}悬浮球">${icon(s.running?'pause':'play')}</button></div>`}
function home(i){if(i>=4)return botanicalHome(i);return `${runCard(i)}${section('权限',null)}${permissionList(i)}${section('随手工具','manage','管理 '+icon('manage').replace('<svg ','<svg style="height:11px;width:11px;vertical-align:-2px;margin-left:2px" '))}${toolGrid(i)}<div class="hint">按住小叶展开快捷，拖动停住后可开始区域截图。</div>`}
function formRow(label,val,action,extra=''){return `<div class="form-row ${action?'clickrow':''}" ${action?`data-action="${action}"`:''} ${extra}><b>${label}</b><span class="value">${val}${action?'　›':''}</span></div>`}
function slider(key,title,min,max,value,unit){return `<div class="slider-row"><label><b>${title}</b><span data-value="${key}">${value}${unit}</span></label><input aria-label="${title}" type="range" data-slider="${key}" min="${min}" max="${max}" value="${value}" data-unit="${unit}"></div>`}
function gesture(i){let s=state[i];return `<h2 class="empty-title">定制你的小叶</h2><div class="preview"><div class="leaf-symbol large" style="${s.color?'background:'+s.color+';':''}opacity:${s.opacity/100};transform:scale(${s.size/65})">${icon('leaf')}</div></div><div class="swatches">${(i>=4?[null,'#2c473e','#6a8e4e','#b0d182','#d6bd66']:[null,'#4d76f5','#789e87','#b086a6','#dbad6a']).map((c,k)=>`<button class="swatch ${(s.color===c)?'active':''}" style="--swatch:${c||'var(--accent)'}" data-action="color" data-color="${c||''}" aria-label="配色 ${k+1}"></button>`).join('')}</div><button class="outline" data-action="art">＋ 自定义图片或 GIF</button>${section('尺寸') }<div class="card">${slider('size','大小',36,150,s.size,' dp')}${slider('opacity','不透明度',30,100,s.opacity,'%')}${slider('gap','边框距离',-100,0,s.gap,' dp')}</div>${section('手势')}<div class="card list-pad">${['单击','双击','长按','上划','下划'].map((n,j)=>formRow(n,s.gestures[j],'gesture',`data-index="${j}"`)).join('')}</div><button class="outline main-action-wide" data-action="reset-gestures">恢复默认手势</button>`}
function settings(i){let s=state[i];return `<h2 class="empty-title">按你的方式使用</h2>${section('行为')}<div class="card list-pad">${['自动吸边','空闲时淡化','触感反馈','增强悬浮层'].map((n,j)=>`<div class="form-row"><b>${n}</b><button class="switch ${s.switches[j]?'':'off'}" data-action="switch" data-index="${j}" aria-label="${n}" aria-pressed="${s.switches[j]}"></button></div>`).join('')}</div>${section('主题')}<div class="card list-pad">${formRow('深色模式',s.theme,'theme')}</div>${section('其他')}<div class="card list-pad">${[['特定应用中的悬浮球','rules'],['找回悬浮球','recover'],['重置悬浮球位置','reset-ball'],['检查更新','update'],['GitHub','github']].map(([n,a])=>formRow(n,'',a)).join('')}</div><div class="settings-caption">空叶悬浮球 · 概念设计<br>界面状态仅在本次演示中保留</div>`}
function phone(i){return document.querySelector(`[data-phone="${i}"]`)}
function render(i,page=state[i].page){state[i].page=page;let p=phone(i);p.querySelector('.modal-shade')?.remove();p.querySelector('.viewport').innerHTML=({home,gesture,settings}[page])(i);p.querySelector('.viewport').scrollTop=0;p.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));p.querySelector('.floating-ball').style.display=state[i].running?'grid':'none'}
function toast(i,text){let p=phone(i);p.querySelector('.toast')?.remove();let n=document.createElement('div');n.className='toast';n.textContent=text;p.appendChild(n);setTimeout(()=>n.remove(),2100)}
function sheet(i,title,body){let p=phone(i);p.querySelector('.modal-shade')?.remove();let modal=document.createElement('div');modal.className='modal-shade';modal.innerHTML=`<div class="sheet"><div class="sheet-handle"></div><div class="row"><h3>${title}</h3><button class="icon-button" data-action="close-sheet" aria-label="关闭选项">${icon('close')}</button></div>${body}</div>`;modal.addEventListener('click',e=>{if(e.target===modal)modal.remove()});p.appendChild(modal)}
function detailTitle(name){return `<div class="detail-title"><button data-action="return" aria-label="返回">${icon('back')}</button>${name}</div>`}
function actionButtons(buttons){return `<div class="bottom-actions">${buttons.map(([ic,name,a])=>`<button data-action="${a}" ${a==='result'?'class="main-action"':''}>${icon(ic)}${name}</button>`).join('')}</div>`}
function detail(i,title,content){let p=phone(i);p.querySelector('.modal-shade')?.remove();p.querySelector('.viewport').innerHTML=detailTitle(title)+content;p.querySelector('.viewport').scrollTop=0}
function openTool(i,id){let label=tools.find(t=>t[0]===id)?.[1]||'区域截图';if(['region','long','screen','record','gif'].includes(id)){state[i].currentTool=id;state[i].recording=false;detail(i,label,`<div class="mock-screen"><div class="mock-paper">让屏幕上的灵感<br>随手留下。<small>KONGYE / 程序生成的演示内容</small></div>${id==='screen'?'':'<div class="capture-frame"></div>'}</div><div class="phone-detail-meta">${id==='long'?'先添加截图，再预览拼接、排序与删除。':id==='record'||id==='gif'?'调整范围与录制选项，预览录制流程。':'选择区域后，可查看文字识别与图片结果。'}</div>${id==='record'||id==='gif'?`<div class="card list-pad">${formRow('分辨率','720p','resolution')}${id==='record'?formRow('声音',state[i].sound,'sound'):''}${formRow('水印','未添加','watermark')}${formRow('隐藏录制球','关闭','hide-record')}</div><button class="primary main-action-wide" data-action="start-record">${id==='gif'?'开始录制 GIF':'开始录屏'}</button>`:actionButtons([['region','选区','selection'],['settings','设置','capture-options'],[id==='long'?'long':'check',id==='long'?'添加一张':'完成截图',id==='long'?'append':'result']])}${id==='long'?'<button class="outline main-action-wide" data-action="long-preview">查看拼接预览</button>':''}`)}else if(id==='notes'){detail(i,'便签',`<div class="card"><div class="tiny muted" style="margin-bottom:10px">我的随手记录</div><textarea class="reading" data-note placeholder="在这里记下灵感…">${escapeHtml(state[i].notes)}</textarea></div><button class="primary main-action-wide" data-action="save-note">保存便签</button>`)}else if(id==='browser'){detail(i,'悬浮浏览器',`<input class="reading" style="min-height:36px;height:36px;padding:9px" aria-label="浏览器地址" value="https://www.bing.com"><div class="mock-screen" style="margin-top:12px;height:280px"><div style="text-align:center"><div style="font-size:27px;font-weight:400">搜索一下。</div><div class="tiny muted" style="margin-top:12px">浏览器页面展示区域</div></div></div>${actionButtons([['back','后退','demo'],['pin','置顶','pin'],['close','收起','return']])}`)}else{detail(i,label,`<input class="reading" style="min-height:38px;height:38px" placeholder="搜索应用" data-app-search><div class="card list-pad" style="margin-top:12px">${['微信','相册','浏览器','设置','日历','文件管理'].map((n,j)=>`<div class="form-row clickrow" data-action="launch-demo" data-app="${n}"><span class="row"><span class="leaf-symbol" style="height:25px;width:25px">${icon(['notes','screen','browser','settings','recent','long'][j])}</span><b>${n}</b></span><span class="muted">›</span></div>`).join('')}</div>`)}}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function result(i){let ocr=state[i].currentTool==='region';detail(i,'截图结果',`${ocr?`${section('文字','translate','翻译')}<textarea class="reading" aria-label="识别文字">让屏幕上的灵感，随手留下。</textarea>${actionButtons([['copy','复制','copy'],['translate','翻译','translate'],['share','分享','share']])}`:''}${section('图片','pin',state[i].pinned?'已置顶':'置顶')}<button class="image-mini" style="width:100%;border:0" data-action="image-preview" aria-label="预览截图">${icon('screen')}</button>${actionButtons([['save','保存','save'],['share','分享','share'],['edit','编辑','editor']])}`)}
const defaultGestures=['快捷菜单','返回','边缘快捷栏','打开空叶软件页面','通知栏'];
document.addEventListener('click',e=>{let global=e.target.closest('[data-global]');if(global){state.forEach((_,i)=>render(i,global.dataset.global));return}let el=e.target.closest('[data-action],[data-page]');if(!el)return;let p=el.closest('[data-phone]');if(!p)return;let i=Number(p.dataset.phone),s=state[i],a=el.dataset.action;if(el.dataset.page){render(i,el.dataset.page);return}let val=Number(el.dataset.index);
switch(a){case'running':s.running=!s.running;render(i);break;case'permission':s.permissions[val]=!s.permissions[val];render(i);toast(i,'演示权限状态已更新');break;case'switch':s.switches[val]=!s.switches[val];el.classList.toggle('off',!s.switches[val]);el.setAttribute('aria-pressed',String(s.switches[val]));break;case'color':s.color=el.dataset.color||null;render(i);break;case'return':render(i);break;case'close-sheet':p.querySelector('.modal-shade')?.remove();break;case'tool':openTool(i,el.dataset.tool);break;case'quick':sheet(i,'按住小叶 · 快捷操作',`<div class="quick-dock">${s.selected.slice(0,8).map(id=>`<button data-action="tool" data-tool="${id}" aria-label="${tools.find(t=>t[0]===id)[1]}">${icon(id)}</button>`).join('')}</div><button class="outline" data-action="manage">管理快捷</button>`);break;
case'manage':sheet(i,'首页工具',`<p class="tiny muted">选择要放在首页的工具</p><div class="tool-select">${tools.map(([id,n])=>`<label class="checktool"><input type="checkbox" data-tool-check="${id}" ${s.selected.includes(id)?'checked':''}>${n}</label>`).join('')}</div><button class="primary main-action-wide" data-action="save-tools">完成</button>`);break;
case'save-tools':s.selected=Array.from(p.querySelectorAll('[data-tool-check]:checked')).map(x=>x.dataset.toolCheck);render(i,'home');toast(i,'首页工具已调整');break;
case'gesture':s.editGesture=val;sheet(i,['单击','双击','长按','上划','下划'][val]+'动作',`<div class="list-pad">${['快捷菜单','返回','边缘快捷栏','打开空叶软件页面','区域截图','长截图','录屏','通知栏','不执行'].map(n=>`<div class="form-row clickrow" data-action="choose-gesture" data-choice="${n}"><b>${n}</b><span class="value">${s.gestures[val]===n?'✓':''}</span></div>`).join('')}</div>`);break;
case'choose-gesture':s.gestures[s.editGesture]=el.dataset.choice;render(i);break;case'reset-gestures':s.gestures=[...defaultGestures];render(i);toast(i,'已恢复默认手势');break;
case'art':sheet(i,'自定义图片或 GIF',`<div class="preview">${icon('screen').replace('<svg ','<svg style="width:36px;height:36px;color:var(--accent)" ')}</div><p class="tiny muted">支持透明 PNG 和 GIF。此处展示自定义外观的界面。</p><button class="primary main-action-wide" data-action="art-preview">预览自定义效果</button>`);break;
case'art-preview':p.querySelector('.modal-shade')?.remove();s.color='#a58bd6';render(i);toast(i,'已切换演示配色');break;
case'theme':sheet(i,'深色模式',`<div class="list-pad">${['跟随系统','浅色模式','深色模式','定时开启'].map(n=>`<div class="form-row clickrow" data-action="choose-theme" data-choice="${n}"><b>${n}</b><span class="value">${s.theme===n?'✓':''}</span></div>`).join('')}</div>`);break;
case'choose-theme':s.theme=el.dataset.choice;render(i);toast(i,'主题偏好：'+s.theme+'（风格对比保持当前配色）');break;
case'rules':detail(i,'特定应用中的悬浮球',`<div class="card list-pad">${['微信','相册','浏览器','设置'].map(n=>`<div class="form-row"><b>${n}</b><select class="select" style="flex:0 0 120px" aria-label="${n}中显示规则"><option>正常显示</option><option>隐身可用</option><option>禁用</option></select></div>`).join('')}</div>`);break;
case'update':sheet(i,'检查更新',`<div style="text-align:center;padding:20px 0">${icon('check').replace('<svg ','<svg style="width:35px;height:35px;color:var(--accent)" ')}<h3>演示版本已是最新</h3><div class="tiny muted">KONGYE · DESIGN PREVIEW</div></div><button class="primary main-action-wide" data-action="close-sheet">知道了</button>`);break;
case'github':case'about':sheet(i,'关于空叶',`<div class="leaf-symbol large" style="margin:12px auto">${icon('leaf')}</div><div style="text-align:center"><h3>空叶悬浮球</h3><p class="tiny muted">一片小叶，随处可用。</p><p class="tiny muted">这是为比较设计方向制作的界面演示。</p></div><button class="outline" data-action="close-sheet">继续体验</button>`);break;
case'recover':s.running=true;render(i);toast(i,'小叶已回到右侧');break;case'reset-ball':toast(i,'演示：悬浮球位置已重置');break;
case'append':s.parts=(s.parts||0)+1;toast(i,'已添加第 '+s.parts+' 张演示截图');break;
case'long-preview':s.parts=Math.max(2,s.parts||0);detail(i,'拼接预览',`<div class="card">${Array.from({length:s.parts},(_,j)=>`<div class="form-row"><span class="row">${icon('screen').replace('<svg ','<svg style="width:20px;height:20px" ')}<b>第 ${j+1} 张</b></span><button class="text-button" data-action="delete-part">删除</button></div>`).join('')}</div><p class="tiny muted">演示截图列表与删除效果</p><button class="primary main-action-wide" data-action="result">确认拼接</button>`);break;case'delete-part':el.closest('.form-row').remove();toast(i,'演示截图已删除');break;
case'result':result(i);break;case'pin':s.pinned=!s.pinned;toast(i,s.pinned?'演示：窗口已置顶':'演示：已取消置顶');break;
case'image-preview':detail(i,'图片预览',`<div class="mock-screen" style="height:330px"><div class="mock-paper">让屏幕上的灵感<br>随手留下。<small>KONGYE FLOAT</small></div></div><button class="primary main-action-wide" data-action="editor">${icon('edit').replace('<svg ','<svg style="width:12px;height:12px;vertical-align:-2px" ')} 编辑图片</button>`);break;
case'editor':detail(i,'编辑图片',`<div class="mock-screen" style="height:260px"><div class="mock-paper">一片小叶<br>随处可用。</div></div><div class="previewtoolbar">${[['crop','裁剪'],['rotate','旋转'],['pen','画笔'],['text','文字'],['rect','画框'],['arrow','箭头'],['edit','序号'],['mosaic','马赛克']].map(([id,n])=>`<button data-action="edit-mode" data-label="${n}">${icon(id)}${n}</button>`).join('')}</div><button class="primary main-action-wide" data-action="result">应用编辑</button>`);break;
case'edit-mode':toast(i,'已选择：'+el.dataset.label);el.style.background='var(--accent)';el.style.color='white';break;
case'translate':detail(i,'文字翻译',`<div class="row" style="margin-bottom:14px"><select class="select" aria-label="源语言"><option>中文</option><option>英语</option><option>日语</option></select><span>→</span><select class="select" aria-label="目标语言"><option>英语</option><option>中文</option><option>日语</option></select></div><textarea class="reading" aria-label="原文">让屏幕上的灵感，随手留下。</textarea>${section('译文')}<textarea class="reading" aria-label="翻译结果">Capture inspiration, right where it happens.</textarea><button class="primary main-action-wide" data-action="copy">复制译文</button>`);break;
case'start-record':s.recording=true;detail(i,'正在录制',`<div class="mock-screen"><div class="playback"><div class="record-time">00:12</div><span class="tiny muted">演示录制时长</span></div></div><p class="phone-detail-meta">录制悬浮球将替代普通悬浮球显示。</p>${actionButtons([['pause','暂停','pause-record'],['stop','停止','record-result'],['close','退出','cancel-record']])}`);break;
case'pause-record':el.innerHTML=icon(el.dataset.paused?'pause':'play')+(el.dataset.paused?'暂停':'继续');el.dataset.paused=el.dataset.paused?'':'1';toast(i,el.dataset.paused?'演示：录制已暂停':'演示：继续录制');break;
case'cancel-record':openTool(i,s.currentTool);break;
case'record-result':detail(i,'录制结果',`<div class="mock-screen" style="height:300px"><div class="playback"><button data-action="play-video" aria-label="播放录制视频">${icon('play')}</button><span class="tiny muted">点击播放 · 演示录制</span></div></div><input aria-label="播放进度" type="range" min="0" max="12" value="0" style="margin-top:18px">${actionButtons([['save','保存','save'],['share','分享','share'],['gif','转为 GIF','convert']])}`);break;
case'play-video':el.innerHTML=icon(el.dataset.playing?'play':'pause');el.dataset.playing=el.dataset.playing?'':'1';toast(i,el.dataset.playing?'演示播放中':'演示已暂停');break;
case'resolution':case'sound':sheet(i,a==='sound'?'录制声音':'录制分辨率',`<div class="list-pad">${(a==='sound'?['无声','手机内部声音','麦克风','内部声音 + 麦克风']:['原始分辨率','1080p','720p','480p']).map(n=>`<div class="form-row clickrow" data-action="record-option" data-choice="${n}"><b>${n}</b><span class="muted">›</span></div>`).join('')}</div>`);break;
case'record-option':s.sound=el.dataset.choice;p.querySelector('.modal-shade')?.remove();toast(i,'已选择：'+el.dataset.choice);break;
case'watermark':sheet(i,'录制水印',`<textarea class="reading" placeholder="输入水印文字" aria-label="水印文字"></textarea><button class="primary main-action-wide" data-action="close-sheet">确认</button>`);break;
case'save-note':s.notes=p.querySelector('[data-note]').value;toast(i,'演示便签已保存');break;
case'launch-demo':toast(i,'演示：打开'+el.dataset.app);break;
case'copy':toast(i,'演示：文字已复制');break;case'save':toast(i,'演示：已保存');break;case'share':sheet(i,'分享',`<div class="quick-dock">${['微信','QQ','更多','复制'].map(n=>`<button data-action="share-done" aria-label="分享到${n}" style="font-size:9px">${n}</button>`).join('')}</div>`);break;case'share-done':p.querySelector('.modal-shade')?.remove();toast(i,'演示：分享完成');break;
case'convert':toast(i,'演示：已转换为 GIF');break;case'selection':toast(i,'演示：选区已调整');break;case'hide-record':toast(i,'演示：已切换隐藏录制球');break;
case'capture-options':sheet(i,'截图选项',`<div class="card list-pad">${formRow('截图格式','PNG')}${formRow('截图质量','原始画质')}</div>`);break;default:toast(i,'界面操作演示')}});
document.addEventListener('input',e=>{let p=e.target.closest('[data-phone]');if(!p)return;let i=Number(p.dataset.phone);if(e.target.dataset.slider){let key=e.target.dataset.slider;state[i][key]=Number(e.target.value);p.querySelector(`[data-value="${key}"]`).textContent=e.target.value+e.target.dataset.unit;let ball=p.querySelector('.preview .leaf-symbol');if(ball){ball.style.opacity=state[i].opacity/100;ball.style.transform=`scale(${state[i].size/65})`}}if(e.target.hasAttribute('data-app-search')){let query=e.target.value;p.querySelectorAll('[data-app]').forEach(n=>n.style.display=n.dataset.app.includes(query)?'flex':'none')}});
state.forEach((_,i)=>render(i));

function collage(){return `<div class="garden-collage" aria-hidden="true"><div class="tile t1"><i class="sun"></i></div><div class="tile t2">${icon('leaf')}</div><div class="tile t3"><span class="sprout"><i></i><b></b></span></div><div class="tile t4"><i class="quarter"></i></div><div class="tile t5"><span class="sprout"><i></i><b></b></span></div><div class="tile t6">${icon('leaf')}</div><div class="tile t7"><i class="sun"></i></div><div class="tile t8"><i class="quarter"></i></div></div>`}
function botanicalHome(i){let s=state[i];if(i===4)return `<div class="garden-state"><div class="garden-hero">${collage()}<div class="garden-title"><span class="garden-kicker">HELLO, LITTLE LEAF.</span><h2>小叶，<br>常伴左右<span>↗</span></h2></div></div><div class="garden-run row"><div><b><span class="dot"></span>${s.running?'小叶正在运行':'小叶暂时休息'}</b><p class="tiny muted" style="margin:4px 0 0">把你的日常，变得轻松一点。</p></div><button class="primary" data-action="running">${s.running?'暂停':'开启'}</button></div></div>${section('让小叶准备好','about','权限指引 ↗')}${permissionList(i)}${section('随手花园','manage','管理工具 +')}${toolGrid(i)}<div class="garden-foot">一片叶子，也有很多可能。${icon('leaf')}</div>`;return `<div class="forest-word"><div class="forest-logo">${icon('leaf')}<strong>kongye<span>®</span></strong></div><div class="forest-sub">随手之间，自在一点。</div></div><div class="forest-run"><div class="row"><span class="forest-eyebrow">FLOATING ASSISTANT</span><span class="forest-signal">${s.running?'● ON':'○ OFF'}</span></div><h2>${s.running?'随时待命。':'稍作休息。'}</h2><div class="row"><span class="tiny">一片小叶，随处可用。</span><button class="forest-control" data-action="running" aria-label="${s.running?'暂停':'开启'}悬浮球">${icon(s.running?'pause':'play')}</button></div></div>${section('权限','about','ACCESS')}${permissionList(i)}${section('常用工具','manage','定制 +')}${toolGrid(i)}<div class="forest-footer"><b>less effort.<br>more freedom.</b><span>KONGYE / FLOAT</span></div>`}
if(botanicalOnly){document.querySelector('.studio-title').textContent='把日常，种进一片绿意。';document.querySelector('.intro').textContent='两份新设计，分别提取植物拼贴与森林绿品牌风格。每台手机可独立操作，也可同时切换页面。';document.title='空叶悬浮球 · 两种植物绿设计';document.querySelector('.source-footer').innerHTML='<b>参考与取舍</b>　左侧：图1的橄榄绿植物配色与几何拼贴，重新组织为空叶的状态与工具；右侧：图2的 #2C473E / #6A8E4E / #B0D182 / #F4F1EA 配色，结合粗字体与胶囊控件。所有图形均由代码绘制。'}
